// FakeWhatsAppServiceServer is the server API for FakeWhatsAppService service.
// All implementations must embed UnimplementedFakeWhatsAppServiceServer
// for forward compatibility.
//
// FakeWhatsAppService scripts the fake WhatsApp of a test build of whatsmeow-net (-tags fakewhatsapp) started with
// --fake-whatsapp, and records what the sidecar sent to it. It is served next to whatsmeow.v1 on the same socket,
// with the same token. It is not part of the whatsmeow.v1 contract and never ships (ADR 0019).
//
// Each slice adds the controls it needs here. Errors are INTERNAL with a message: the fake adds no ErrorReason.
type FakeWhatsAppServiceServer interface {
	// DeliverMessage makes WhatsApp deliver a decrypted message to a session's client, and returns once the client's
	// event handlers ran. As whatsmeow does at the pin, the client answers with a receipt only when every handler
	// succeeded (message.go:459-462, 489-495); that shows in WaitForSent. A message left unanswered is delivered again
	// at the device's next login, and never while the connection stays up, as measured live (ARCHITECTURE §14, #10).
	// A session without a client is an error: the fake never answers on behalf of a client the sidecar did not create.
	DeliverMessage(context.Context, *DeliverMessageRequest) (*DeliverMessageResponse, error)
	// DeliverPollVote makes WhatsApp deliver a poll vote from sender to a session's client, as DeliverMessage does. The
	// fake encrypts it as the voter's device would, with whatsmeow's own message secret code
	// (DangerousInternalClient.EncryptMsgSecret, internals.go:430-431) and the poll's secret as the voter's device has
	// it: the secret the session's message node with the poll's id carried, as WhatsApp delivered the account's poll,
	// else the session's store's, as the poll's sender sent it to every member. It names the poll by a key as the voter
	// sees it (msgsecret.go:130-151): its own when the voter sent the poll, else the poll's sender as the remote JID in a
	// direct chat and as the participant in a group. A poll with no secret either way is an error: such a vote is
	// DeliverMessage's, with a message of its own.
	DeliverPollVote(context.Context, *DeliverPollVoteRequest) (*DeliverPollVoteResponse, error)
	// DeliverUndecryptableMessage makes WhatsApp deliver a message the session's client cannot decrypt, and returns once
	// the client's event handlers ran. whatsmeow sends its retry receipt and ack before it dispatches
	// UndecryptableMessage, whatever the handlers return (message.go:418-437); the fake records neither. A resend that
	// decrypts is a DeliverMessage with the same id. A session without a client is an error.
	DeliverUndecryptableMessage(context.Context, *DeliverUndecryptableMessageRequest) (*DeliverUndecryptableMessageResponse, error)
	// WaitForSent returns the first thing the session's client sent to WhatsApp after the entry `after`, and waits
	// until there is one. Only the call's deadline or cancellation ends the wait. The log lives in the sidecar process,
	// so it starts again, at index 1, after a restart.
	WaitForSent(context.Context, *WaitForSentRequest) (*WaitForSentResponse, error)
	// LinkDevice makes the phone link the session's device: the client stores the device under jid as whatsmeow does
	// after a pair success (handlePair, pair.go:222-240), then dispatches PairSuccess and returns once its event handlers
	// ran. Without a Pair call open it is the quick way to a paired session. With one, the client's QR channel then sends
	// success and closes, as whatsmeow's does (qrchan.go:189-190), and the client logs in again after WhatsApp's 515
	// (connectionevents.go:26-38): off the node queue it uploads its pre-keys, unless FailNextPreKeyUpload, and
	// dispatches Connected (connectionevents.go:187-204).
	LinkDevice(context.Context, *LinkDeviceRequest) (*LinkDeviceResponse, error)
	// RotateQrCode makes the session's open QR channel send the next code, as whatsmeow's does when the previous one
	// expires (qrchan.go:92-110). The first code comes when the client connects. No QR channel open is an error.
	RotateQrCode(context.Context, *RotateQrCodeRequest) (*RotateQrCodeResponse, error)
	// ExpireQrCodes makes the session's QR codes run out: the QR channel sends timeout and closes, and the client
	// disconnects without a Disconnected event, as whatsmeow's does (qrchan.go:77-84). No QR channel open is an error.
	ExpireQrCodes(context.Context, *ExpireQrCodesRequest) (*ExpireQrCodesResponse, error)
	// DropConnection makes the connection of a session that is pairing drop: the client dispatches Disconnected off the
	// node queue (client.go:614-624), and its QR channel then sends timeout and closes (qrchan.go:196-197). whatsmeow
	// does not reconnect an unpaired client (client.go:650). No QR channel open is an error. It returns before the
	// handlers run.
	DropConnection(context.Context, *DropConnectionRequest) (*DropConnectionResponse, error)
	// HoldNextLogin makes the session's next login, after a connect or a reset's reconnect, hold Connected until
	// ReleaseLogin, so the session stays connecting or reconnecting: whatsmeow dispatches it on a goroutine of its own
	// after two IQs (connectionevents.go:187-204), while the offline sync's OfflineSyncCompleted comes on the node queue
	// (connectionevents.go:87-90), so CompleteOfflineSync can come first.
	HoldNextLogin(context.Context, *HoldNextLoginRequest) (*HoldNextLoginResponse, error)
	// ReleaseLogin dispatches the session's held Connected off the node queue, and returns once its handlers ran. No
	// held login is an error.
	ReleaseLogin(context.Context, *ReleaseLoginRequest) (*ReleaseLoginResponse, error)
	// FailNextPreKeyUpload makes the session's next login after a link fail to upload the pre-keys: whatsmeow only logs
	// that (prekeys.go:84-87), never sets PreKeysUploaded, and still dispatches Connected (connectionevents.go:187-204).
	FailNextPreKeyUpload(context.Context, *FailNextPreKeyUploadRequest) (*FailNextPreKeyUploadResponse, error)
	// FailNextPairPhone makes WhatsApp answer the session's next phone pairing request with an IQ error of code
	// (pair-code.go:104-127): 429 is whatsmeow's ErrIQRateOverLimit (errors.go:198).
	FailNextPairPhone(context.Context, *FailNextPairPhoneRequest) (*FailNextPairPhoneResponse, error)
	// FailNextConnect makes the session's next connect fail with an error whatsmeow does not retry. Without it a
	// connect succeeds, and a linked client then gets Connected, as whatsmeow does once WhatsApp accepts the login.
	FailNextConnect(context.Context, *FailNextConnectRequest) (*FailNextConnectResponse, error)
	// FailNextLogout makes the session's next logout get no answer from WhatsApp: whatsmeow's unlink request times out
	// (ErrIQTimedOut, request.go:180-181), and the client stays connected with its device, as whatsmeow's does.
	FailNextLogout(context.Context, *FailNextLogoutRequest) (*FailNextLogoutResponse, error)
	// RaisePermanentDisconnect makes WhatsApp end the session's connection with one of the six whatsmeow
	// PermanentDisconnect events at the pin (types/events/events.go:118-128), dispatched off the node queue as
	// whatsmeow does; the client is disconnected and does not reconnect. For logged_out the client also deletes its
	// device concurrently, as whatsmeow does (connectionevents.go:37-44, 130-136). It returns before the handlers run.
	RaisePermanentDisconnect(context.Context, *RaisePermanentDisconnectRequest) (*RaisePermanentDisconnectResponse, error)
	// RegisterUser adds a user to WhatsApp's directory, which every session's lookups read: IsOnWhatsApp, GetUserInfo,
	// and the LID that UpdateBlocklist and a send to a phone number fetch (send.go:341-365). An unregistered number is
	// not on WhatsApp. Registering a phone_jid again replaces it.
	RegisterUser(context.Context, *RegisterUserRequest) (*RegisterUserResponse, error)
	// SetProfilePicture sets what WhatsApp answers for the profile picture of a user or a group; without one it answers
	// that there is none.
	SetProfilePicture(context.Context, *SetProfilePictureRequest) (*SetProfilePictureResponse, error)
	// DeliverContactNotification makes WhatsApp send the session's client a picture or status notification. As
	// whatsmeow does, the client dispatches Picture or UserAbout on the node queue and ignores the handlers' result
	// (notification.go:93-117, 451-468, 474); it returns once the handlers ran. A session without a client is an error.
	DeliverContactNotification(context.Context, *DeliverContactNotificationRequest) (*DeliverContactNotificationResponse, error)
	// SyncContact makes an app state sync deliver a contact's saved name: the client stores it, then dispatches Contact,
	// as whatsmeow does (appstate.go:301-305). The session must be linked.
	SyncContact(context.Context, *SyncContactRequest) (*SyncContactResponse, error)
	// FailNextContactQuery makes WhatsApp answer the session's next contact query (IsOnWhatsApp, GetUserInfo,
	// GetProfilePictureInfo, GetBlocklist, UpdateBlocklist) with an IQ error of code: 429 is whatsmeow's
	// ErrIQRateOverLimit (errors.go:198).
	FailNextContactQuery(context.Context, *FailNextContactQueryRequest) (*FailNextContactQueryResponse, error)
	// DeliverPresence makes WhatsApp send a user's presence to the session's client, which dispatches events.Presence on
	// its node queue (presence.go:39-58), and returns once the client's event handlers ran. whatsmeow answers nothing.
	// A session without a client is an error.
	DeliverPresence(context.Context, *DeliverPresenceRequest) (*DeliverPresenceResponse, error)
	// DeliverChatPresence makes WhatsApp send a user's chat state to the session's client, which dispatches
	// events.ChatPresence on its node queue (presence.go:18-37), and returns once the client's event handlers ran.
	// whatsmeow answers nothing. A session without a client is an error.
	DeliverChatPresence(context.Context, *DeliverChatPresenceRequest) (*DeliverChatPresenceResponse, error)
	// SetPushName makes the app state sync set the account's push name, as whatsmeow does for the push name setting: it
	// sets the device's push name and saves the device (appstate.go:373-383). Until then SendPresence fails with
	// whatsmeow's ErrNoPushName (presence.go:67-68). A session without a client is an error.
	SetPushName(context.Context, *SetPushNameRequest) (*SetPushNameResponse, error)
	// FailNextUploads makes the session's next count uploads fail after they encrypted the file, as a POST that fails
	// does (upload.go:291-302). Each attempt shows in WaitForSent as a MediaUpload.
	FailNextUploads(context.Context, *FailNextUploadsRequest) (*FailNextUploadsResponse, error)
	// ExpireMedia makes WhatsApp answer every download of direct_path with status, as whatsmeow reports it
	// (ErrMediaDownloadFailedWith403, 404 or 410, errors.go:134-136).
	ExpireMedia(context.Context, *ExpireMediaRequest) (*ExpireMediaResponse, error)
	// CorruptMedia flips one byte of the ciphertext stored at direct_path, so every download of it fails verification
	// (ErrInvalidMediaEncSHA256, download-to-file.go:218-219) and leaves ciphertext in the file, as whatsmeow does.
	CorruptMedia(context.Context, *CorruptMediaRequest) (*CorruptMediaResponse, error)
	// HoldNextDownload makes the session's next download write part of the file and then wait until its call ends.
	HoldNextDownload(context.Context, *HoldNextDownloadRequest) (*HoldNextDownloadResponse, error)
	// AnswerMediaRetry makes the phone answer the session's media retry request for message_id, which WaitForSent
	// showed as a MediaRetryReceipt: it encrypts the answer with the media key the request carried, as the phone does,
	// or supplies encrypted bytes unchanged, and returns once the client's event handlers ran. With reupload, the
	// phone uploads the media at from_direct_path again, to a new path. whatsmeow acknowledges the notification whatever the handlers return
	// (notification.go:512-513), so nothing shows in WaitForSent. No request for message_id is an error.
	AnswerMediaRetry(context.Context, *AnswerMediaRetryRequest) (*AnswerMediaRetryResponse, error)
	// DeliverReceipt makes WhatsApp deliver a receipt to a session's client, and returns once the client's event
	// handlers ran. With SynchronousAck, whatsmeow acks a receipt only when every handler succeeded
	// (maybeDeferredAck, receipt.go:21-43, 115-128); a retry receipt it acks inside its retry handler, before the
	// dispatch, whatever the handlers return (receipt.go:34-38, retry.go:184-192). The ack shows in WaitForSent. A
	// session without a client is an error.
	DeliverReceipt(context.Context, *DeliverReceiptRequest) (*DeliverReceiptResponse, error)
	// RateLimitNextSends makes the session's next count sends fail as WhatsApp's rate limit fails them: an IQ before the
	// node is written answers 429 (ErrIQRateOverLimit, errors.go:198), so nothing is sent.
	RateLimitNextSends(context.Context, *RateLimitNextSendsRequest) (*RateLimitNextSendsResponse, error)
	// HoldNextSend makes the session's next send write its node, which WaitForSent shows, and then get no answer until
	// ReleaseSend: like whatsmeow's, it then returns ctx.Err() when its context ends (send.go:445-455), and when the
	// connection ends, a DisconnectedError 5 s later, once whatsmeow's wait for a reconnect is over (request.go:185-202),
	// since the fake never reconnects on its own. ReleaseSend makes WhatsApp accept it.
	HoldNextSend(context.Context, *HoldNextSendRequest) (*HoldNextSendResponse, error)
	// ReleaseSend makes WhatsApp answer the session's held send: it succeeds. No held send is an error.
	ReleaseSend(context.Context, *ReleaseSendRequest) (*ReleaseSendResponse, error)
	// RefuseNextSend makes WhatsApp answer the session's next message node, which WaitForSent shows, with an error code,
	// as whatsmeow reads such an answer (ErrServerReturnedError, send.go:468-470). A send HoldNextSend holds too is
	// refused at once, and nothing stays held.
	RefuseNextSend(context.Context, *RefuseNextSendRequest) (*RefuseNextSendResponse, error)
	// AddGroup puts a group on WhatsApp's side, which every session's group calls read and change. Its members are
	// phone-number JIDs; in a LID-addressed group WhatsApp answers each by the LID RegisterUser gave it, with the phone
	// number beside it, and by the phone number when it has none. Adding a jid again replaces the group.
	AddGroup(context.Context, *AddGroupRequest) (*AddGroupResponse, error)
	// DeliverGroupNotification makes WhatsApp send the session's client a w:gp2 notification of a change to a group,
	// which need not be on WhatsApp's side. The client dispatches GroupInfo on its node queue, and returns once the
	// handlers ran; as whatsmeow does, it acks the notification only when every handler succeeded
	// (notification.go:495-508, maybeDeferredAck receipt.go:115-128), and the ack, of class "notification", the
	// request's id and type "w:gp2", shows in WaitForSent. The group calls' notifications are acked the same way. A
	// session without a client is an error.
	//
	// The group calls themselves notify the members as WhatsApp would, the member who made the change included
	// [inferred: whatsmeow's own note that the server echoes a change, send.go:665]: a member added, or one that joins by
	// link, gets a create notification (JoinedGroup), and every other member a change. WhatsApp's codes are [inferred]:
	// a non-admin's change to a locked group's info, to its settings or to its participants is 403, and to its invite
	// link 401 (whatsmeow's ErrGroupInviteLinkUnauthorized, group.go:432); a group the session is not in is 403 and an
	// unknown one 404 (group.go:674-678); adding a member is 409, and removing, promoting or demoting a non-member 404,
	// for that participant; a reset invite code is 410 (group.go:516-519), and any code the fake does not know, malformed
	// or not, 400 bad-request [observed: #120 live run 2026-11-04], for a join and for the group info of a link, which
	// joins nothing and lists every member; a member who is not an admin may add
	// participants when the group's member add mode is all_member_add, and changes the mode only as an admin (403); a
	// created group has the mode its create asked for, all_member_add unless told otherwise, as whatsmeow asks
	// (group.go:59-63), though what WhatsApp answers after a create is [unknown], and a group AddGroup put there has none
	// until one is set; a disappearing timer is changed as the group's info is, and one not offered is 400
	// (whatsmeow's ErrInvalidDisappearingTimer, send.go:687-690); the creator gets no
	// JoinedGroup for its own group; the create answer lists a participant WhatsApp refused, with its error. WhatsApp's
	// time on these calls is fixed, 2026-11-01T12:00:00Z, so a test knows each time they answer and notify; an invite
	// RefuseGroupAdd offers expires 72 hours after it.
	DeliverGroupNotification(context.Context, *DeliverGroupNotificationRequest) (*DeliverGroupNotificationResponse, error)
	// RefuseGroupAdd makes WhatsApp refuse to add a user to any group, by CreateGroup or by adding them, with code; with
	// invite, WhatsApp offers an invite instead, as for a user whose privacy settings ask for one (group.go:729-739).
	RefuseGroupAdd(context.Context, *RefuseGroupAddRequest) (*RefuseGroupAddResponse, error)
	// FailNextGroupQuery makes WhatsApp answer the session's next group call with an IQ error of code: 429 is
	// whatsmeow's ErrIQRateOverLimit (errors.go:198).
	FailNextGroupQuery(context.Context, *FailNextGroupQueryRequest) (*FailNextGroupQueryResponse, error)
	// SyncChatState makes the phone change a chat's state, and the session's client sync it as whatsmeow does after a
	// server_sync notification: on its node queue, holding its app state lock while it fetches (appstate.go:46-47,
	// notification.go:483-485), and dispatching the change once it let go of the lock (appstate.go:36-38). While the
	// collection is corrupted (CorruptAppState) the fetch fails instead: whatsmeow dispatches AppStateSyncError holding
	// the lock (appstate.go:176), and the change does not arrive. With full_sync the change arrives as a full sync's,
	// marked FromFullSync, as it does after pairing. It returns once the client's event handlers ran. A session without
	// a client is an error.
	SyncChatState(context.Context, *SyncChatStateRequest) (*SyncChatStateResponse, error)
	// GetPhoneChatState reads what the phone shows for a chat: what the session's writes (SendAppState) and SyncChatState
	// made it.
	GetPhoneChatState(context.Context, *GetPhoneChatStateRequest) (*GetPhoneChatStateResponse, error)
	// CorruptAppState makes the session's copy of an app state collection out of step with WhatsApp's, as a mismatching
	// LTHash does [inferred: the server cannot verify the hash, so it shows only when another device's patch arrives]:
	// a write to it is rejected with a 409 whose patches do not verify (appstate.go:616-623), and a sync of it fails.
	// A full sync (FetchAppState with fullSync) repairs it, unless unrecoverable: then the full sync fails too, as one
	// whose snapshot does not verify does (appstate/decode.go:288-295).
	CorruptAppState(context.Context, *CorruptAppStateRequest) (*CorruptAppStateResponse, error)
	// HoldFullSync makes the session's next full syncs wait, holding the client's app state lock, until it is called
	// again with hold false. A full sync is recorded (Sent.app_state_full_sync) before it waits.
	HoldFullSync(context.Context, *HoldFullSyncRequest) (*HoldFullSyncResponse, error)
	// CompleteOfflineSync makes WhatsApp tell the session's client that it sent everything the client missed while
	// offline: the client dispatches OfflineSyncCompleted on its node queue, in order with the messages before it
	// (connectionevents.go:72-90). It returns once the client's event handlers ran, with the index of the newest entry of
	// the Sent log then. A session without a client is an error.
	CompleteOfflineSync(context.Context, *CompleteOfflineSyncRequest) (*CompleteOfflineSyncResponse, error)
	// DeliverHistorySync makes the phone send a history sync blob: the media server keeps the blob, zlib-compressed as
	// WhatsApp's are, in a file that outlives the process (or the notification carries it inline), and the session's
	// client gets the notification, a protocol message from the account's own phone, as DeliverMessage delivers one.
	// The client's DownloadHistorySync reads it back (Sent.media_download, unless inline) and its DeleteMedia deletes
	// it (Sent.media_delete); ExpireMedia with the returned direct path makes it expired. It returns once the client's
	// event handlers ran. A session without a client is an error.
	DeliverHistorySync(context.Context, *DeliverHistorySyncRequest) (*DeliverHistorySyncResponse, error)
	// GetPairingDeviceProps reads the history options the session's latest pairing sent: the process-wide
	// store.DeviceProps as they were when the phone linked the device (LinkDevice), which whatsmeow sends only in the
	// registration payload (store/clientpayload.go:174-183).
	GetPairingDeviceProps(context.Context, *GetPairingDevicePropsRequest) (*GetPairingDevicePropsResponse, error)
	// RecordEvent records an event in the session's outbox as it is, under no key, past every slice's mapping, and
	// returns once it is committed; the outbox gives it its seq. It is the one way to stream the client an event the
	// sidecar never records, such as one the client cannot read, whose skip and ack are the client's own (ARCHITECTURE
	// §8.7, #122). A session that does not exist is an error.
	RecordEvent(context.Context, *RecordEventRequest) (*RecordEventResponse, error)
	mustEmbedUnimplementedFakeWhatsAppServiceServer()
}

